const selectedPrompts = [];
const chosenCategories = [];
const seed = Date.now().toString(36);
const categoryPools = {};

for (let i = 0; i < sceneCount; i++) {
  const cat = shuffledCategories[i % shuffledCategories.length];
  chosenCategories.push(cat);

  // 2. In the chosen category, shuffle the prompts
  if (!categoryPools[cat] || categoryPools[cat].length === 0) {
    categoryPools[cat] = shuffle(PROMPT_POOLS[cat]);
  }

  const picked = categoryPools[cat].shift();
  selectedPrompts.push(`${picked}, scene seed ${seed}_${i + 1}`);
}

